+    public async Task<bool> UpdateShipmentStatusAsync(int id, ShipmentUpdateDto update)
+    {
+        var shipment = await db.Shipments.FindAsync(id);
+        if (shipment is null) return false;
+
+        shipment.Status = update.Status;
+        if (update.Status == ShipmentStatus.Delivered)
+            shipment.ActualDelivery = DateTime.UtcNow;
+
+        await db.SaveChangesAsync();
+        return true;
+    }
+}
