@page "/shipments"
@attribute [Authorize]

@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services

@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h2>📋 Shipment Dashboard</h2>

<div class="row mb-3 align-items-end">
    <div class="col-auto">
        <label class="form-label fw-bold">Filter by Status</label>
        <select class="form-select" @onchange="OnStatusFilterChanged">
            <option value="">All</option>
            @foreach (var s in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@s" selected="@(statusFilter == s.ToString())">@s</option>
            }
        </select>
    </div>
    <div class="col-auto">
        <button class="btn btn-outline-secondary" @onclick="LoadShipments">
            🔄 Refresh
        </button>
    </div>
    <div class="col">
        <span class="text-muted">@shipments.Count shipment(s)</span>
    </div>
</div>

@if (loading)
{
    <p><em>Loading shipments…</em></p>
}
else if (!shipments.Any())
{
    <div class="alert alert-info">No shipments found.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Destination</th>
                    <th>Recipient</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var shipment in shipments)
                {
                    <tr>
                        <td><code>@shipment.TrackingNumber</code></td>
                        <td>@shipment.Destination</td>
                        <td>@shipment.RecipientName</td>
                        <td>
                            <span class="badge @GetStatusBadgeClass(shipment.Status)">
                                @shipment.Status
                            </span>
                        </td>
                        <td>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                        <td>
                            @if (editingId == shipment.Id)
                            {
                                <div class="d-flex gap-1">
                                    <select class="form-select form-select-sm" style="width:auto" @bind="newStatus">
                                        @foreach (var s in Enum.GetValues<ShipmentStatus>())
                                        {
                                            <option value="@s">@s</option>
                                        }
                                    </select>
                                    <button class="btn btn-sm btn-success" @onclick="() => SaveStatus(shipment.Id)">Save</button>
                                    <button class="btn btn-sm btn-secondary" @onclick="CancelEdit">Cancel</button>
                                </div>
                            }
                            else
                            {
                                <button class="btn btn-sm btn-outline-primary" @onclick="() => StartEdit(shipment)">
                                    Update
                                </button>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@if (!string.IsNullOrEmpty(message))
{
    <div class="alert @(messageIsError ? "alert-danger" : "alert-success") alert-dismissible mt-3">
        @message
        <button type="button" class="btn-close" @onclick="() => message = null"></button>
    </div>
}

@code {
    private List<ShipmentDto> shipments = [];
    private bool loading = true;
    private string? statusFilter;
    private int? editingId;
    private ShipmentStatus newStatus;
    private string? message;
    private bool messageIsError;

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        loading = true;
        shipments = await ShipmentService.GetShipmentsAsync(statusFilter);
        loading = false;
    }

    private async Task OnStatusFilterChanged(ChangeEventArgs e)
    {
        statusFilter = e.Value?.ToString();
        await LoadShipments();
    }

    private void StartEdit(ShipmentDto shipment)
    {
        editingId = shipment.Id;
        newStatus = shipment.Status;
    }

    private void CancelEdit()
    {
        editingId = null;
    }

    private async Task SaveStatus(int id)
    {
        var success = await ShipmentService.UpdateShipmentStatusAsync(id, new ShipmentUpdateDto { Status = newStatus });
        if (success)
        {
            message = "Status updated successfully.";
            messageIsError = false;
            editingId = null;
            await LoadShipments();
        }
        else
        {
            message = "Failed to update status.";
            messageIsError = true;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info text-dark",
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-warning text-dark",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-dark",
        _ => "bg-secondary"
    };
}

@page "/track"

@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services

@inject IShipmentService ShipmentService
@inject NavigationManager Nav

<PageTitle>Track Shipment</PageTitle>

<h2>📍 Track Your Shipment</h2>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g. TRK-20260001)"
                   @bind="trackingNumber" @bind:event="oninput"
                   @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="Search" disabled="@(searching || string.IsNullOrWhiteSpace(trackingNumber))">
                @if (searching)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Search
            </button>
        </div>
    </div>
</div>

@if (notFound)
{
    <div class="alert alert-warning">
        No shipment found for tracking number <strong>@searchedNumber</strong>. Please check and try again.
    </div>
}
else if (shipment is not null)
{
    <div class="card shadow-sm">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h5 class="mb-0">Tracking: <code>@shipment.TrackingNumber</code></h5>
            <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Origin</dt>
                        <dd>@shipment.Origin</dd>

                        <dt>Destination</dt>
                        <dd>@shipment.Destination</dd>

                        <dt>Recipient</dt>
                        <dd>@shipment.RecipientName</dd>

                        <dt>Description</dt>
                        <dd>@shipment.Description</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Shipped Date</dt>
                        <dd>@shipment.ShippedDate.ToString("MMMM dd, yyyy")</dd>

                        <dt>Estimated Delivery</dt>
                        <dd>
                            <strong class="@(shipment.Status == ShipmentStatus.Delayed ? "text-danger" : "text-success")">
                                @shipment.EstimatedDelivery.ToString("MMMM dd, yyyy")
                            </strong>
                        </dd>

                        @if (shipment.ActualDelivery.HasValue)
                        {
                            <dt>Actual Delivery</dt>
                            <dd class="text-success fw-bold">@shipment.ActualDelivery.Value.ToString("MMMM dd, yyyy")</dd>
                        }
                    </dl>
                </div>
            </div>

            @* Visual status progress bar *@
            <div class="mt-3">
                <h6>Shipment Progress</h6>
                <div class="progress" style="height: 30px;">
                    <div class="progress-bar @GetProgressBarClass(shipment.Status)"
                         role="progressbar"
                         style="width: @GetProgressPercent(shipment.Status)%"
                         aria-valuenow="@GetProgressPercent(shipment.Status)"
                         aria-valuemin="0" aria-valuemax="100">
                        @shipment.Status
                    </div>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [SupplyParameterFromQuery(Name = "t")]
    private string? InitialTracking { get; set; }

    private string? trackingNumber;
    private string? searchedNumber;
    private ShipmentDto? shipment;
    private bool notFound;
    private bool searching;

    protected override async Task OnInitializedAsync()
    {
        if (!string.IsNullOrWhiteSpace(InitialTracking))
        {
            trackingNumber = InitialTracking;
            await Search();
        }
    }

    private async Task Search()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        searching = true;
        notFound = false;
        shipment = null;
        searchedNumber = trackingNumber.Trim();

        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchedNumber);
        notFound = shipment is null;
        searching = false;
    }

    private void HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            _ = Search();
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info text-dark",
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-warning text-dark",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-dark",
        _ => "bg-secondary"
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-dark",
        _ => "bg-primary"
    };

    private static int GetProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 25,
        ShipmentStatus.InTransit => 50,
        ShipmentStatus.OutForDelivery => 75,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Delayed => 50,
        ShipmentStatus.Returned => 100,
        _ => 0
    };
}

