+@using Microsoft.AspNetCore.Authorization
+@using ShipmentTracker.Client.Models
+@using ShipmentTracker.Client.Services
+
+@inject IShipmentService ShipmentService
+
+<PageTitle>Dispatcher Dashboard</PageTitle>
+
+<h2>📋 Shipment Dashboard</h2>
+
+<div class="row mb-3 align-items-end">
+    <div class="col-auto">
+        <label class="form-label fw-bold">Filter by Status</label>
+        <select class="form-select" @onchange="OnStatusFilterChanged">
+            <option value="">All</option>
+            @foreach (var s in Enum.GetValues<ShipmentStatus>())
+            {
+                <option value="@s" selected="@(statusFilter == s.ToString())">@s</option>
+            }
+        </select>
+    </div>
+    <div class="col-auto">
+        <button class="btn btn-outline-secondary" @onclick="LoadShipments">
+            🔄 Refresh
+        </button>
+    </div>
+    <div class="col">
+        <span class="text-muted">@shipments.Count shipment(s)</span>
+    </div>
+</div>
+
+@if (loading)
+{
+    <p><em>Loading shipments…</em></p>
+}
+else if (!shipments.Any())
+{
+    <div class="alert alert-info">No shipments found.</div>
+}
+else
+{
+    <div class="table-responsive">
+        <table class="table table-striped table-hover">
+            <thead class="table-dark">
+                <tr>
+                    <th>Tracking #</th>
+                    <th>Destination</th>
+                    <th>Recipient</th>
+                    <th>Status</th>
+                    <th>Est. Delivery</th>
+                    <th>Actions</th>
+                </tr>
+            </thead>
+            <tbody>
+                @foreach (var shipment in shipments)
+                {
+                    <tr>
+                        <td><code>@shipment.TrackingNumber</code></td>
+                        <td>@shipment.Destination</td>
+                        <td>@shipment.RecipientName</td>
+                        <td>
+                            <span class="badge @GetStatusBadgeClass(shipment.Status)">
+                                @shipment.Status
+                            </span>
+                        </td>
+                        <td>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
+                        <td>
+                            @if (editingId == shipment.Id)
+                            {
+                                <div class="d-flex gap-1">
+                                    <select class="form-select form-select-sm" style="width:auto" @bind="newStatus">
+                                        @foreach (var s in Enum.GetValues<ShipmentStatus>())
+                                        {
+                                            <option value="@s">@s</option>
+                                        }
+                                    </select>
+                                    <button class="btn btn-sm btn-success" @onclick="() => SaveStatus(shipment.Id)">Save</button>
+                                    <button class="btn btn-sm btn-secondary" @onclick="CancelEdit">Cancel</button>
+                                </div>
+                            }
+                            else
+                            {
+                                <button class="btn btn-sm btn-outline-primary" @onclick="() => StartEdit(shipment)">
+                                    Update
+                                </button>
+                            }
+                        </td>
+                    </tr>
+                }
+            </tbody>
+        </table>
+    </div>
+}
+
+@if (!string.IsNullOrEmpty(message))
+{
+    <div class="alert @(messageIsError ? "alert-danger" : "alert-success") alert-dismissible mt-3">
+        @message
+        <button type="button" class="btn-close" @onclick="() => message = null"></button>
+    </div>
+}
+
+@code {
+    private List<ShipmentDto> shipments = [];
+    private bool loading = true;
+    private string? statusFilter;
+    private int? editingId;
+    private ShipmentStatus newStatus;
+    private string? message;
+    private bool messageIsError;
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadShipments();
+    }
+
+    private async Task LoadShipments()
+    {
+        loading = true;
+        shipments = await ShipmentService.GetShipmentsAsync(statusFilter);
+        loading = false;
+    }
+
+    private async Task OnStatusFilterChanged(ChangeEventArgs e)
+    {
+        statusFilter = e.Value?.ToString();
+        await LoadShipments();
+    }
+
+    private void StartEdit(ShipmentDto shipment)
+    {
+        editingId = shipment.Id;
+        newStatus = shipment.Status;
+    }
+
+    private void CancelEdit()
+    {
+        editingId = null;
+    }
+
+    private async Task SaveStatus(int id)
+    {
+        var success = await ShipmentService.UpdateShipmentStatusAsync(id, new ShipmentUpdateDto { Status = newStatus });
+        if (success)
+        {
+            message = "Status updated successfully.";
+            messageIsError = false;
+            editingId = null;
+            await LoadShipments();
+        }
+        else
+        {
+            message = "Failed to update status.";
+            messageIsError = true;
+        }
+    }
+
+    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
+    {
+        ShipmentStatus.Delivered => "bg-success",
+        ShipmentStatus.InTransit => "bg-primary",
+        ShipmentStatus.OutForDelivery => "bg-info text-dark",
+        ShipmentStatus.Pending => "bg-secondary",
+        ShipmentStatus.PickedUp => "bg-warning text-dark",
+        ShipmentStatus.Delayed => "bg-danger",
+        ShipmentStatus.Returned => "bg-dark",
+        _ => "bg-secondary"
+    };
+}
+

